def in_name_group(state: GameState, pokemon: PokemonInPlay, group: str) -> bool:
    """場のポケモン ``pokemon`` の今の姿のカード（``form_def``。「ばける」・［へんしん］）の名前のグループが ``group`` か（v0.96。「自分の場の「アンノーン」」）。印刷の名前の
    完全一致・カード id では決めない。うらのカード（マチスの秘策）の名前のグループは読めない（``HiddenPropertyRead``。FD1）。"""
    return form_def(state, pokemon).name_group == group


@dataclass(frozen=True)
class RetreatCost:
    """「にげる」でトラッシュするエネルギーの数（v0.46。``retreat_cost``）。

    - ``printed``: バトル場のポケモンのいちばん上のカードの「にげる」の数（p.310）
    - ``increases``: 決まって増やす特殊能力（(持つポケモンの番号, ``PowerKey`` の文字列, 数)。ねんちゃくえき）
    - ``reductions``: 少なくできる特殊能力（同じ形。にげるサポート。少なくするかは選べる）
    - ``stadium_increases``（v0.57）: 決まって増やす場のスタジアム（(スタジアムカード, 数)。ロケット団の特訓ジム）。特殊能力とは別に記録する
    - ``stadium_reductions``（v0.57）: 決まってへらす場のスタジアム（(スタジアムカード, 数)。ハナダシティジム。選べない）
    - ``marker_increases``（v0.90）: 決まって増やすマーカー（(マーカーの種類, 数)。ベトベトマーカーの「「にげる」時トラッシュするエネルギーが、1つぶん多く必要になる」。
      ［ねんちゃくえき］と同じ書き方なので、同じ増やす数として当てはめる（CP2・ふうせんのみの読み方も同じ））。特殊能力・スタジアムとは別に記録する
    - ``power_zeroed``（v0.96）: 「にげる」ときに必要なエネルギーをすべてなくす、はたらいている特殊能力（(持つポケモンの番号, ``PowerKey`` の文字列)。アンノーンZ の［ZOOM］）。
      ふうせんのみ（``zeroed``。ついているどうぐ）と同じ「すべてなくなる」で、数の読み方（``readings``・CP2）は同じに当てはめる。ふうせんのみだけの処理（「にげる」とき、
      このカードをトラッシュする・BB1）には当てはめない（``engine._retreat`` は ``zeroed`` だけを見る）。2 つ以上あっても重ならない（どれも 0 にするだけ）

    増やす数とへらす数をまとめ、最後に 0 で下限をつける（``maximum`` = max(0, 印刷の数 + 増やす数 − 決まってへらす数)、``minimum`` = max(0, それ − 少なくできる数)）。
    へらす数が印刷の数より多く、増やす数もあるときは、先にへらして 0 で止めてから増やす読み方（``floor_first_minimum``・``floor_first_maximum``）と最後に下限をつける
    読み方で、トラッシュしてよい数が変わる。どちらの読み方も記録から決まらない（CP2）ので、読み方で答えが変わる数をトラッシュする「にげる」は止める（``engine._retreat``）。
    スタジアムのない場合の数・範囲・止める数は v0.56 と同じ。"""

    printed: int
    increases: tuple[tuple[int, str, int], ...] = ()
    reductions: tuple[tuple[int, str, int], ...] = ()
    stadium_increases: tuple[tuple[int, int], ...] = ()
    stadium_reductions: tuple[tuple[int, int], ...] = ()
    zeroed: tuple[int, ...] = ()  # v0.81: ふうせんのみ（「にげる」ときに必要な「エネルギー」は、すべてなくなる）のカード
    marker_increases: tuple[tuple[str, int], ...] = ()  # v0.90: ベトベトマーカー
    power_zeroed: tuple[tuple[int, str], ...] = ()  # v0.96: ［ZOOM］（「にげる」ときに必要な「エネルギー」は、すべてなくなる）
    # v0.118: 決まって増やすワザの持続する効果（(効果を与えたワザ（``AttackKey`` の文字列）, 数)。しめつづけるの ``RetreatCostIncrease``）。［ねんちゃくえき］・ベトベトマーカーと同じ
    # 増やす数として当てはめる（CP2・ふうせんのみの読み方も同じ）。特殊能力・スタジアム・マーカーとは別に記録する
    effect_increases: tuple[tuple[str, int], ...] = ()

    @property
    def _zeroing(self) -> bool:
        """「すべてなくなる」があるか（ふうせんのみ・特殊能力。v0.96）。"""
        return bool(self.zeroed or self.power_zeroed)

    @property
    def _increase(self) -> int:
        return (sum(amount for _, _, amount in self.increases) + sum(amount for _, amount in self.stadium_increases)
                + sum(amount for _, amount in self.marker_increases) + sum(amount for _, amount in self.effect_increases))

    @property
    def _forced_reduction(self) -> int:
        return sum(amount for _, amount in self.stadium_reductions)

    @property
    def _optional_reduction(self) -> int:
        return sum(amount for _, _, amount in self.reductions)

    @property
    def maximum(self) -> int:
        if self._zeroing:
            return max(high for _, high in self.readings)
        return max(0, self.printed + self._increase - self._forced_reduction)

    @property
    def minimum(self) -> int:
        if self._zeroing:
            return min(low for low, _ in self.readings)
        return max(0, self.printed + self._increase - self._forced_reduction - self._optional_reduction)

    @property
    def readings(self) -> tuple[tuple[int, int], ...]:
        """トラッシュしてよい数の範囲（下限, 上限）の読み方ごとの並び（v0.81）。ふうせんのみ（``zeroed``）がなければ、最後に下限をつける読み方と、先にへらして 0 で止める
        読み方（v0.46 の CP2 の 2 つ）。ふうせんのみがあれば、「すべてなくなる」を最後に当てはめる読み方（0）と、先に当てはめる読み方（印刷の数を 0 として、増やす・へらす数を
        当てはめる 2 つ）。読み方で答えが変わる数は CP2 で止める（``floor_ambiguous``）。v0.96: ［ZOOM］（``power_zeroed``）も同じ「すべてなくなる」として当てはめる。"""
        if not self._zeroing:
            return ((max(0, self.printed + self._increase - self._forced_reduction - self._optional_reduction),
                     max(0, self.printed + self._increase - self._forced_reduction)),
                    (self.floor_first_minimum, self.floor_first_maximum))
        first = _dataclass_replace(self, printed=0, zeroed=(), power_zeroed=())
        return ((0, 0),) + first.readings

    @property
    def floor_first_maximum(self) -> int:
        """へらす数を先に当てはめて 0 で止めてから、増やす数を加える読み方の上限（v0.57。CP2 の比べ）。"""
        return max(0, self.printed - self._forced_reduction) + self._increase

    @property
    def floor_first_minimum(self) -> int:
        """へらす数を先に当てはめて 0 で止めてから、増やす数を加える読み方の下限（CP2 の比べ）。"""
        return max(0, self.printed - self._forced_reduction - self._optional_reduction) + self._increase

    def _last(self, count: int) -> bool:
        return self.minimum <= count <= self.maximum

    def _first(self, count: int) -> bool:
        return self.floor_first_minimum <= count <= self.floor_first_maximum

    def allows(self, count: int) -> bool:
        """どちらかの読み方で正しい数か（両方で正しくなければ ``WRONG_RETREAT_COST``）。v0.81: ふうせんのみがあれば、どれかの読み方（``readings``）で正しい数か。"""
        if self._zeroing:
            return any(low <= count <= high for low, high in self.readings)
        return self._last(count) or self._first(count)

    def floor_ambiguous(self, count: int) -> bool:
        """``count`` 枚が、読み方の一方では正しく、もう一方では正しくない（CP2）。v0.81: ふうせんのみがあれば、読み方（``readings``）のどれかで正しく、どれかで正しくない。"""
        if self._zeroing:
            fits = [low <= count <= high for low, high in self.readings]
            return any(fits) and not all(fits)
        return self._last(count) != self._first(count)

    @property
    def modified(self) -> bool:
        return bool(self.increases or self.reductions or self.stadium_increases or self.stadium_reductions or self.zeroed or self.marker_increases
                    or self.power_zeroed or self.effect_increases)


def retreat_cost(state: GameState, player: int) -> RetreatCost:
    """プレイヤー ``player`` のバトル場のポケモンが「にげる」ときにトラッシュするエネルギーの数（v0.46。公開の問い合わせ。``RetreatCost``）。増やすのは相手の
    はたらいている［ねんちゃくえき］、少なくできるのは自分のはたらいている［にげるサポート］。状態を変えず、乱数を使わない。バトル場にポケモンがいなければ ``ValueError``。
    v0.47: バトル場がなにかの化石・ピッピ人形（場での役割のあるカード）なら、にげるエネルギーの数が決まらない（PF2）ので ``UnsupportedError``
    （``UNRESOLVED_PLAY_AS_POKEMON_RETREAT``。``engine._retreat`` と同じ問い）。v0.57: 場のスタジアム（ロケット団の特訓ジムは決まって増やし、ハナダシティジムは
    「カスミのポケモン」なら決まってへらす。``stadium_retreat_terms``）も当てはめる。v0.90: バトル場のポケモンのベトベトマーカー（決まって 1 増やす）も当てはめる。
    v0.96: 自分のベンチのはたらいている［ZOOM］（``ZeroGroupRetreatCostFromBench``）は、バトル場のポケモンの今の姿のカードが名前のグループ（「アンノーン」）なら、すべてなくす
    （``power_zeroed``）。グループは［ZOOM］がはたらくときだけ読む（うらのカードの名前は読まない）。"""
    active = state.players[player].active
    if active is None:
        raise ValueError(f"プレイヤー {player} のバトル場にポケモンがいない")
    definition = form_def(state, active)  # v0.49: 今の姿のカードのにげるエネルギー（［へんしん］・「ばける」）
    if definition.play_role is not None:
        raise UnsupportedError(PLAY_AS_POKEMON_RETREAT_CODE, f"バトル場のポケモン {active.pokemon_id}: {PLAY_AS_POKEMON_RETREAT_REASON}")
    increases, reductions, power_zeroed = [], [], []
    for owner, holder, key, effect in continuous_powers(state, (IncreaseOpponentActiveRetreatCost, ReduceOwnActiveRetreatCost, ZeroGroupRetreatCostFromBench)):
        if isinstance(effect, IncreaseOpponentActiveRetreatCost) and owner != player:
            increases.append((holder.pokemon_id, str(key), effect.amount))
        elif isinstance(effect, ReduceOwnActiveRetreatCost) and owner == player:
            reductions.append((holder.pokemon_id, str(key), effect.amount))
        elif isinstance(effect, ZeroGroupRetreatCostFromBench) and owner == player and in_name_group(state, active, effect.group):
            power_zeroed.append((holder.pokemon_id, str(key)))
    stadium_increases, stadium_reductions = stadium_retreat_terms(state, player, active)
    # v0.90: ベトベトマーカー（「「ベトベトマーカー」をのせているポケモンは、「にげる」時トラッシュするエネルギーが、1つぶん多く必要になる」。のせているポケモンについて 1 つぶん。
    # 「のっていなければ、1つのせる」ので 2 つにはならない）
    markers = ((MARKER_STICKY, STICKY_MARKER_RETREAT_INCREASE),) if has_marker(active, MARKER_STICKY) else ()
    # v0.118: しめつづけるの持続する効果（次の相手の番、「にげる」ときに必要な「エネルギー」が多くなる。受けた順）
    effects = tuple((effect.attack, effect.amount) for effect in retreat_cost_increases(state, active))
    # v0.81: ふうせんのみ（ついているどうぐ。「にげる」ときに必要な「エネルギー」は、すべてなくなる）
    return RetreatCost(definition.retreat_cost, tuple(increases), tuple(reductions), stadium_increases, stadium_reductions, balloon_berries(state, active),
                       markers, tuple(power_zeroed), effects)


ALLERGIC_POLLEN_TEXT = "このカードが場にいる限り、誰もトレーナーカードを使うことができない。「ねむり・マヒ・こんらん」状態の時、この力は消える。"


@dataclass(frozen=True)
class PreventTrainerUse(ContinuousPower):
    """このカードが場にいる限り、誰もトレーナーカードを使うことができない。ねむり・マヒ・こんらん状態の時、この力は消える（v0.46。わるいラフレシア（PMCG4-010）の
    ［アレルギーかふん］。kyuura の印刷の文面）。

    - お互いのプレイヤーが、手札のトレーナーカードを使えない（``engine._play_trainer`` が、カードを手札から出す前に ``TRAINER_PREVENTED`` で拒否する。状態・乱数・
      ログは変わらない）。場（バトル場・ベンチ）のどこでもはたらく。ねむり・マヒ・こんらんで消える。かがくへんかガスで消える
    - すでに使ってポケモンについているトレーナー（プラスパワー・ディフェンダー）は、使い終わっているので、その効果は続く（使う操作ではない）。使っている最中のトレーナー
      （ポケモン育て屋さんでこのカードを場に出した）も、使い終える
    """

    implementation_id = "prevent_trainer_use"
    what = "トレーナーカードを使えなくする特殊能力"

    def texts(self) -> tuple[str, ...]:
        return (ALLERGIC_POLLEN_TEXT,)


def trainer_lock_sources(state: GameState) -> tuple[tuple[int, int, str], ...]:
    """今はたらいている、トレーナーカードを使えなくする特殊能力（v0.46。［アレルギーかふん］）の (持ち主, 持つポケモンの番号, ``PowerKey`` の文字列)。空なら
    トレーナーカードを使える（ほかの条件による）。公開の問い合わせ。状態を変えず、乱数を使わない。"""
    return tuple((owner, holder.pokemon_id, str(key)) for owner, holder, key, _ in continuous_powers(state, PreventTrainerUse))


IMMUNITY_TEXT = "このカードは、「どく・ねむり・マヒ・こんらん」状態にならない。(なんらかの原因で「ねむり・マヒ・こんらん」状態になっているとき、この力は使えない)"


@dataclass(frozen=True)
class SpecialConditionImmunity(ContinuousPower):
    """このカードは、どく・ねむり・マヒ・こんらん状態にならない。なんらかの原因でねむり・マヒ・こんらん状態になっているとき、この力は使えない（v0.46。カビゴン
    （PMCG2-047）の［めんえき］。kyuura の印刷の文面）。

    - 特殊状態にする効果（ワザ・特殊能力のどれでも）を受けても、その特殊状態にならない（``conditions`` の付ける処理の共通の入口で防ぐ。ログ
      ``special_condition_prevented``）。すでにある特殊状態を回復する効果ではない（どくは残る）
    - すでにねむり・マヒ・こんらん状態（かがくへんかガスで消えていた間になった）なら使えない。どく状態だけなら使える（ねむり・マヒ・こんらんにならない・どくの
      上書き（特殊などく）もしない）
    - 防がれる特殊状態について、原典で決められない場合の確かめ（マヒの再付与・特殊などくの上書き・「ダメージを与えた後」の効果）は、防がれて結果が変わらないので
      聞かない（``resolution.programs.Status``）。効果を決めるコインは、効果の要素が無効なのではなく、効果を受けて特殊状態にならないので、今までどおり投げる
    """

    implementation_id = "special_condition_immunity"
    what = "特殊状態にならない特殊能力"

    def texts(self) -> tuple[str, ...]:
        return (IMMUNITY_TEXT,)


def status_immunity(state: GameState, owner: int, pokemon: PokemonInPlay) -> PowerKey | StatusImmunityWhileActive | None:
    """場のポケモン ``pokemon``（持ち主 ``owner``）の、今はたらいている特殊状態にならない特殊能力（v0.46。［めんえき］）の ``PowerKey``。v0.84: なければ、バトル場にいる
    ``pokemon`` が受けている「きらめきタッチ」の効果（``state.StatusImmunityWhileActive``。「バトル場にいるかぎり」）。どちらもなければ None。"""
    from .continuous import power_suppressed  # continuous.py は effects.py を読み込むので、使うときに読み込む

    for slot in powers_of(state, pokemon):  # v0.49: 今持つ特殊能力
        effect = slot.effect
        if isinstance(effect, SpecialConditionImmunity) and effect.located(state, owner, pokemon) and effect.status_allows(pokemon) \
                and not power_suppressed(state, slot.power, pokemon):
            return slot.key
    guard = status_immunity_while_active(pokemon)
    if guard is not None and state.players[owner].active is pokemon:
        return guard
    return status_immunity_next_turn(state, pokemon)  # v0.85: しんぴのこな（次の相手の番）


def received_power_damage(state: GameState, owner: int, receiver: PokemonInPlay, source: PokemonInPlay, amount: int) -> tuple[int, tuple[DamageModifier, ...]]:
    """特殊能力のダメージ（はんげき・わるいねぞう・こっそりかみつく。ワザによるダメージではない）を ``receiver`` が受けるときの、受けるダメージ全体を書く常にはたらく
    特殊能力（なぞのかべ・ふしぎなバリアー）を当てはめた数と、当てはめた変更（v0.46）。p.321 の計算の順番（ワザによるダメージの計算）は当てはめず、受けるポケモンの
    特殊能力だけを、持つ特殊能力の順に当てはめる（2 つ以上が当てはまる場合は今の対応カードでは起こらない。起こったらエンジンの不具合として止める）。

    v0.75（DB1）: ``receiver`` に、今の番にはたらく「もろばバサミ」の効果（``DoubledDamage``。「このカードが受けるダメージは2倍になる」）があり、ダメージが 0 より大きいなら、
    特殊能力のダメージに当てはめるかが決まらないので ``UnsupportedError``（量を変える前。呼ぶ側が状態を変える前に聞く）。"""
    if amount > 0 and doubled_damage(state, receiver) is not None:
        raise UnsupportedError(DOUBLED_POWER_DAMAGE_CODE, f"ポケモン {receiver.pokemon_id} の特殊能力のダメージ {amount}: {DOUBLED_POWER_DAMAGE_REASON}")
    reduction = damage_reduction(state, receiver)
    if amount > 0 and reduction is not None and reduction.non_attack_unresolved:
        # v0.125（IF1）: 「ふくらむ」の効果がはたらく番の特殊能力のダメージ。減らすかで受けるダメージが変わるので止める（DB1 と同じく、量を変える前。呼ぶ側が状態を変える前に聞く）。
        # ワザのダメージ（p.321 の 8 段階）・どく（ポケモンチェックはどちらの番でもない。p.323）は、ここを通らない
        raise UnsupportedError(INFLATE_NON_ATTACK_DAMAGE_CODE, f"ポケモン {receiver.pokemon_id} の特殊能力のダメージ {amount}: {INFLATE_NON_ATTACK_DAMAGE_REASON}")
    growl = reduced_damage_to_source(state, source)
    if amount > 0 and growl is not None and not expires_at_turn_start(growl) and growl.source_card == receiver.card:
        # v0.76: 「なきごえ」（説明は「…このカードにダメージを与える時」で、ワザに限らない）を受けたポケモンが、はたらく番に、効果を与えたポケモンに特殊能力のダメージを
        # 与える。v0.76 は、はたらく番（受けたポケモンの持ち主の番）にこのポケモンが与えうる特殊能力のダメージは今の対応カードでは起こらないとして、内部エラーにしていた
        # v0.121（GN1。docs/hand-bench-attack-conditions-v0.121.md 2 章）: v0.114 のエレキッドの［わんぱくパンチ］（自分の番に使う。相手の対戦ポケモンに特殊能力のダメージ）で
        # 起こる。ワザ以外のダメージを減らすかは記録で決まらず、受けるダメージが変わるので止める（呼ぶ側は状態を変える前に聞く）
        raise UnsupportedError(GROWL_NON_ATTACK_DAMAGE_CODE,
                               f"「なきごえ」を受けたポケモン {source.pokemon_id} → 効果を与えたポケモン {receiver.pokemon_id} への特殊能力のダメージ {amount}: {GROWL_NON_ATTACK_DAMAGE_REASON}")
    applied = []
    for holder_owner, holder, key, effect in continuous_powers(state):
        if holder is not receiver:
            continue
        modifier = effect.received_damage_modifier(state, holder, _power_label(state, holder, key), source)
        if modifier is not None:
            applied.append(modifier)
    if len(applied) > 1:
        raise RuntimeError(f"特殊能力のダメージを受けるポケモン {receiver.pokemon_id} に、受けるダメージを変える特殊能力が 2 つ以上ある（順番が決まらない。エンジンの不具合）")
    per = state.rules.damage_per_counter
    printed = amount
    for modifier in applied:
        amount = modifier.apply(amount, per)
    # v0.78: 受けるポケモンについている鋼エネルギー（NIP1X-010。「ダメージを受けるとき、そのダメージは「-10」」。ワザに限らない）。受けるダメージを変える特殊能力と
    # 両方が当てはまり、当てはめる順番で量が変わるなら、ワザでないダメージには p.321 の段階がないので決まらない（MT1）
    reduced, used = energy_received_damage(state, receiver, amount)
    cards = energy_damage_reducers(state, receiver) if printed > 0 else ()
    if cards and applied:
        other, _ = energy_received_damage(state, receiver, printed)
        for modifier in applied:
            other = modifier.apply(other, per)
        if other != reduced:
            raise UnsupportedError(METAL_POWER_ORDER_CODE, f"ポケモン {receiver.pokemon_id} の特殊能力のダメージ {printed}（{applied[0].label}・鋼エネルギー {list(cards)}）: "
                                   + METAL_POWER_ORDER_REASON)
    applied.extend(DamageModifier(step=7, amount=-METAL_REDUCTION, label=state.card_def(uid).name_ja, source=uid) for uid in used)
    if printed > 0:
        _non_attack_damage_question(state, receiver, source, printed, amount)
    return reduced, tuple(applied)


def _non_attack_damage_question(state: GameState, receiver: PokemonInPlay, source: PokemonInPlay | None, printed: int, amount: int) -> None:
    """v0.97（DF2）: ワザでない特殊能力のダメージ ``printed`` を ``receiver`` が受けるとき、場の常にはたらく特殊能力のうち、当てはめるかが決まらないもの（``non_attack_damage_modifier``。
    受けるポケモンでないベンチの力も見る。［NORMAL df］は「「無色」ポケモンからダメージを受けるとき」とワザと書かない）を当てはめると最終の量が変わるなら止める（``UnsupportedError``。
    量を変える前。呼ぶ側が状態を変える前に聞く。v0.75 の DB1 と同じ扱い）。比べ方は v0.79 の ``non_attack_change_matters``（鋼エネルギーの前・あとのすべての順番。``amount`` は受ける
    ポケモン自身の受けるダメージを変える特殊能力を当てはめたあとの量）で、0 以下は「ダメージを受けなかった」として 0 にそろえる（「-30」で負になるため）。同じ力が 2 匹以上でも
    当てはめるのは多くても 1 つ（CR-UNOWN-DF-AT-MOST-ONE。同じ変更は 1 つにまとめる）。p.321 のワザのダメージの段階は使わない。"""
    per = state.rules.damage_per_counter
    uncertain: dict[tuple, DamageModifier] = {}
    for _, holder, key, effect in continuous_powers(state):
        modifier = effect.non_attack_damage_modifier(state, holder, _power_label(state, holder, key), receiver, source)
        if modifier is not None:
            uncertain.setdefault((modifier.operation, modifier.amount, modifier.threshold), modifier)
    if not uncertain:
        return
    changes = tuple((lambda value, m=m: max(0, m.apply(value, per))) for m in uncertain.values())
    if non_attack_change_matters(state, receiver, amount, changes):
        raise UnsupportedError(POWER_DAMAGE_RECEIVED_POWER_CODE, f"ポケモン {receiver.pokemon_id} の特殊能力のダメージ {printed}（{[m.label for m in uncertain.values()]}）: "
                               f"{POWER_DAMAGE_RECEIVED_POWER_REASON}")


def received_modifiers_log(applied: tuple[DamageModifier, ...]) -> tuple[tuple, ...]:
    """ワザでないダメージに当てはめた、受けるダメージを変える特殊能力の記録（ログの ``received_modifiers``。(発生源のカード, 計算, しきい値, 数)）。"""
    return tuple((m.source, m.operation, m.threshold, m.amount) for m in applied)


def confusion_power_modifiers(state: GameState, pokemon: PokemonInPlay, attack_status: frozenset[int] | None) -> list[str]:
    """こんらんしたワザの 20（ワザを使ったポケモン ``pokemon`` が自分に受ける）を、ワザのダメージ（このポケモンが与えるダメージ）として扱うなら当てはまる、常に
    はたらく特殊能力の名前（v0.46。くつろぐかおり・きょうぼう・なぞのかべ・ふしぎなバリアー）。こんらんの 20 がワザによるダメージか・このポケモンが与えるダメージかは
    決まらない（v0.3c）ので、当てはまるものがあれば、コインの前に止める（``procedures.confusion_damage_problem``）。"""
    # v0.99: ワザ（``attack``）は None。こんらんの 20 は、もとのワザの内容に関わらない（p.309 の手順 5）ので、ワザの名前で限られる特殊能力（［PERFORM］の「めざめるパワー」）の
    # 「そのワザのダメージ」ではない（v0.27 の「つるぎのまい」の「「きりさく」のダメージ」と同じ分類。``attack_damage_modifiers`` の説明）
    return [modifier.label for modifier in continuous_attack_damage_modifiers(state, pokemon, pokemon, attack=None, attack_status=attack_status,
                                                                              ignore_status=False)]


# --- v0.46 のワザ（エリカのフシギソウ・わるいオコリザル・わるいラフレシア・エリカのフシギバナ・エリカのタマタマ・エリカのナッシー）


@dataclass(frozen=True)
class DamageThenSelfConfuse(AttackEffect):
    """相手の対戦ポケモンにダメージの目安の数字ぶんのダメージを与えた後、自分（ワザを使ったポケモン）をこんらん状態にする（v0.46。わるいオコリザルの「あばれくるう」。
    kyuura の印刷の文面「ダメージを与えた後、自分は「こんらん」状態になる。」）。

    - 要素の並びは v0.17b の「たおれこむ」と同じ形（``Damage`` → ``Status(CONFUSION, target=SELF, after_damage="damage")``）。ダメージ → ダメージを受けたときの効果の窓
      → 自分をこんらん。自分が HP 以上なら、処理の対象がないのでこんらんにしない（p.309）
    - ダメージを与えなかったとき（ディフェンダーで 0・「ダメージを受けない」・「とうめい」・なぞのかべで 0）は「ダメージを与えた後」の効果を処理するかが決まらない
      （Z23。既存の問いを使う）
    - ［きょうぼう］の +30 は、このダメージを計算する時にこんらん状態のときだけ（あばれくるうで自分をこんらんにするのは、ダメージのあと）
    """

    implementation_id = "damage_then_self_confuse"

    def check(self, attack: Attack) -> list[str]:
        return _check_damage_then_effect(attack, "自分をこんらん状態にする") + _check_exact_text(
            attack, "ダメージのあと自分をこんらん状態にするワザ", ("ダメージを与えた後、自分は「こんらん」状態になる。",))


@dataclass(frozen=True)
class CoinsTimesDamageSelfConfuse(AttackEffect):
    """コインを ``coins`` 枚投げて「おもて」の数 × ``per`` のダメージ。``at_least`` 枚以上「おもて」なら、自分（ワザを使ったポケモン）をこんらん状態にする（v0.46。
    わるいラフレシアの「はなびらのうず」。kyuura の印刷の文面。文末の「。」がない書き方も、ある書き方も受け付ける）。

    - 同じ ``coins`` 枚のコイン（ワザ全体のコイン ``Coin``）の「おもて」の数で、ダメージと自分のこんらんの両方を決める（要素ごとに投げ直さない）。``Damage`` は
      「おもて」の数 × ``per``（``HeadsOfCoin``）、``Status(CONFUSION, target=SELF, gate=("coin", AtLeast(at_least)))``
    - 自分のこんらんは自分への効果なので、相手が「ダメージを受けない」状態でもコインを投げる（v0.34 の ``void_coin_question``）。自分が HP 以上なら処理の対象がない
    """

    coins: int
    per: int
    at_least: int
    implementation_id = "coins_times_damage_self_confuse"

    def __post_init__(self) -> None:
        if type(self.coins) is not int or self.coins < 2 or type(self.at_least) is not int or not 1 <= self.at_least <= self.coins:
            raise ValueError(f"コインの枚数 {self.coins!r}・こんらんになる「おもて」の数 {self.at_least!r} が正しくない")
        _positive_tens(self.per, "「おもて」1 枚あたりのダメージ")

    def check(self, attack: Attack) -> list[str]:
        text = f"コインを{self.coins}枚投げて「おもて」の数×{self.per}のダメージ。{self.at_least}枚以上「おもて」なら、自分は「こんらん」状態になる"
        problems = _check_form(attack, "コインの数でダメージを与えて自分をこんらんにするワザ", damage="modified", modifier="×")
        if attack.damage != self.per:
            problems.append(f"ダメージの目安の数字 {attack.damage!r} と、登録した「おもて」1 枚あたりのダメージ {self.per} が違う")
        return problems + _check_exact_text(attack, "コインの数でダメージを与えて自分をこんらんにするワザ", (text, text + "。"))


GROWTH_TEXT = "コインを投げて「おもて」なら、自分の手札にある「{type}」エネルギーカードを最大{n}枚、このカードにつける。"


def hand_basic_energy(state: GameState, player: int, energy_type: EnergyType) -> list[int]:
    """プレイヤー ``player`` の手札の ``energy_type`` の基本エネルギーカード（手札の並び。v0.46）。"""
    return [uid for uid in state.players[player].hand if state.card_def(uid).is_basic_energy and state.card_def(uid).provides is energy_type]


@dataclass(frozen=True)
class AttachEnergyFromHandOnHeads(AttackEffect):
    """コインを投げて「おもて」なら、自分の手札にある ``energy_type`` エネルギーカードを最大 ``max_cards`` 枚、このカード（ワザを使ったポケモン）につける（v0.46。
    エリカのフシギバナの「せいちょう」。kyuura の印刷の文面）。

    - コイン（``Coin``）→「おもて」なら決定 ``ATTACH_FROM_HAND``（ワザを使ったプレイヤー。手札の ``energy_type`` の基本エネルギーカード。0〜min(``max_cards``, 枚数)）→
      つける（``zones.attach_energy_from_hand``。手札からつける通常の操作・あまごいと同じカードの動かし方）。つけたら ``after_energy_attached``
    - 手札からつける通常の操作（p.310。1 番に 1 枚。``energy_attachments_this_turn``）・特殊能力でつけた枚数（``energy_attached_by_powers_this_turn``）には数えない
      （ワザの効果。別の処理）
    - 手札にそのエネルギーカードがなければ、処理の対象がないのでコインを投げない（v0.38 の ``has_target``）。あるときに 0 枚を選べるかは決まらない（「最大2枚」が
      0 枚を含むか。v0.31 の HC7 と同じ問い。答えのときに止める）
    - 特殊エネルギーは選べない（説明は「「草」エネルギーカード」。今の写しに特殊エネルギーのカードはない）
    """

    energy_type: EnergyType
    max_cards: int
    implementation_id = "attach_energy_from_hand_on_heads"

    def __post_init__(self) -> None:
        if type(self.max_cards) is not int or self.max_cards < 1:
            raise ValueError(f"つける枚数の最大は 1 以上（{self.max_cards!r}）")

    def check(self, attack: Attack) -> list[str]:
        text = GROWTH_TEXT.format(type=self.energy_type.ja, n=self.max_cards)
        # v0.75: ヒマナッツ（PRN-032）の「せいちょう」の書き方（「このカードにつける」が「自分につける」。どちらもワザを使ったポケモン。同じ意味）
        variant = text.replace("、このカードにつける。", "、自分につける。")
        return _check_form(attack, "手札のエネルギーカードを自分につけるワザ", damage="none") + _check_exact_text(attack, "手札のエネルギーカードを自分につけるワザ", (text, variant))

    def decision_problems(self, state: GameState, use: AttackUse, decision: PendingDecision) -> list[str]:
        candidates = hand_basic_energy(state, use.player, self.energy_type)
        return _decision_form(decision, _label(state, use), kind=ATTACH_FROM_HAND, player=use.player, choices=(0, min(self.max_cards, len(candidates))),
                              options=candidates)


SPREAD_SOLAR_BEAM_TEXT = "相手の控えポケモンを{n}匹選び、それらのポケモンにも、「弱点・抵抗力」に関係なく、それぞれ{d}ダメージ。"


@dataclass(frozen=True)
class DamageThenExactBenchTargets(AttackEffect):
    """相手の対戦ポケモンにダメージの目安の数字ぶんのダメージ。相手の控えポケモンを ``targets`` 匹選び、「弱点・抵抗力」に関係なく、それぞれ ``bench_damage``
    ダメージ（v0.46。エリカのフシギバナの「かくさんソーラービーム」。kyuura の印刷の文面）。

    - 要素は v0.39 の ``ChosenBenchDamages`` の ``exact``（ちょうど ``targets`` 匹。「最大」の v0.39 の「ギガスパーク」と混ぜない。0 匹・少ない数は選べない）
    - 相手に控えがいなければ、処理の対象がないので選ばない（p.309）。控えが 1 匹以上で ``targets`` 匹より少ないときに、いるだけ選ぶのか、その内容を処理しないのかは
      決まらない（v0.44 の FC1 と同じ問い「説明が決まった数を選ばせるとき、選べるものが足りない」。宣言の前に止まる）
    """

    targets: int
    bench_damage: int
    implementation_id = "damage_then_exact_bench_targets"

    def __post_init__(self) -> None:
        if type(self.targets) is not int or self.targets < 2:
            raise ValueError(f"選ぶ数は 2 以上（{self.targets!r}）")
        _positive_tens(self.bench_damage, "控えポケモンへのダメージ")

    def check(self, attack: Attack) -> list[str]:
        text = SPREAD_SOLAR_BEAM_TEXT.format(n=self.targets, d=self.bench_damage)
        return _check_form(attack, "相手の控えを決まった数選んでダメージを与えるワザ", damage="fixed") + _check_exact_text(
            attack, "相手の控えを決まった数選んでダメージを与えるワザ", (text,))

    def decision_problems(self, state: GameState, use: AttackUse, decision: PendingDecision) -> list[str]:
        bench = state.players[1 - use.player].bench
        return _decision_form(decision, _label(state, use), kind=SELECT_POKEMON, player=use.player, choices=(self.targets, self.targets),
                              options=(p.pokemon_id for p in bench))


@dataclass(frozen=True)
class HalveDamageNextTurn(AttackEffect):
    """次の相手の番、このカードが受けるダメージは半分（切りすて）になる（ダメージ以外の効果はそのまま）（v0.46。エリカのタマタマの「リフレクター」。kyuura の印刷の
    文面）。

    - 自分自身に与える持続する効果 ``state.HalvedDamage``（はたらく番は次の相手の番。消える契機は v0.4b と同じ）。はたらく番に受けるワザのダメージの p.321 の 8 段階で、
      半分にしてダメージカウンターの単位で切りすてる（``damage.HALVE_DOWN``）。［くつろぐかおり］（常にはたらく特殊能力。切り上げ）とは、はたらく条件・期限・丸めの
      向きが違い、半分にする計算だけを共通にする
    - ダメージ以外の効果は受ける（「ダメージを受けない」状態・「ワザをうけない」状態とは別）
    """

    implementation_id = "halve_damage_next_turn"

    def check(self, attack: Attack) -> list[str]:
        return _check_form(attack, "次の相手の番に受けるダメージを半分にするワザ", damage="none") + _check_exact_text(
            attack, "次の相手の番に受けるダメージを半分にするワザ", ("次の相手の番、このカードが受けるダメージは半分(切りすて)になる。(ダメージ以外の効果はそのまま)",
                                                                # v0.79: エレブー（PR1-010）の「ひかりのかべ」・チコリータ（neo1-002）の「リフレクター」の書き方（意味は同じ）
                                                                "次の相手の番で、このカードがうけるダメージは半分(切り捨て)になる。(ダメージ以外の効果はそのまま)",
                                                                "次の相手の番、このカードが受けるダメージは半分(切りすて)になる。(ダメージ以外の効果は受ける)"))

    def halved_terms(self) -> tuple[type]:
        from .state import HalvedDamage

        return (HalvedDamage,)


PSYCHIC_EXCHANGE_TEXT = "自分の手札をすべて山札にもどし、山札をよく切る。その後、カードを{n}枚引いて、手札にする。"


@dataclass(frozen=True)
class ShuffleHandIntoDeckThenDraw(AttackEffect):
    """自分の手札をすべて山札にもどし、山札をよく切る。その後、カードを ``count`` 枚引いて、手札にする（v0.46。エリカのナッシーの「サイコエクスチェンジ」。kyuura の
    印刷の文面）。

    - もどす（相手に見せない。v0.44 の ``zones.return_hand_cards_to_deck``。手札の並びの順。決定はない（すべて））→ 切る（1 回。``programs.shuffle_in_attack``）→ 引く
      （``zones.draw_cards``。山札が足りなければ引けるだけ。効果で引くときの規定。p.312）。もどす前に引かない・もどしたカードを見せない
    - 手札がなくても、山札を切って引く（説明の文はそれぞれ別の内容。p.309）
    - 要素の並びの最後の要素（先読みでは山札を切らない。引いたカードを使う要素があとにない）
    """

    count: int
    implementation_id = "shuffle_hand_into_deck_then_draw"

    def __post_init__(self) -> None:
        if type(self.count) is not int or self.count < 1:
            raise ValueError(f"引く枚数は 1 以上（{self.count!r}）")

    def check(self, attack: Attack) -> list[str]:
        # v0.114: ピィ（neo1-070）の「ピピピ」の書き方（「その山札をよく切る」「山札からカードを…引いて」。同じ意味）も受け付ける
        texts = (PSYCHIC_EXCHANGE_TEXT.format(n=self.count), SHUFFLE_HAND_DRAW_FROM_DECK_TEXT.format(n=self.count))
        return _check_form(attack, "手札を山札にもどして引くワザ", damage="none") + _check_exact_text(attack, "手札を山札にもどして引くワザ", texts)


